// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.text;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.assertj.core.api.Assertions.within;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.BooleanLiteral;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.TEXTF;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.junit.jupiter.api.Test;

class TextFunctionsTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static Literal str(String s) {
		return VF.createLiteral(s);
	}

	private static double dbl(Literal l) {
		return l.doubleValue();
	}

	@Test
	void editDistances() {
		assertThat(new Levenshtein().evaluate(VF, str("kitten"), str("sitting")).intValue()).isEqualTo(3);
		assertThat(new Levenshtein().evaluate(VF, str(""), str("abc")).intValue()).isEqualTo(3);
		assertThat(new Levenshtein().evaluate(VF, str("😀a"), str("a")).intValue()).isEqualTo(1);
		assertThat(new DamerauLevenshtein().evaluate(VF, str("ca"), str("abc")).intValue()).isEqualTo(2);
		assertThat(new DamerauLevenshtein().evaluate(VF, str("ab"), str("ba")).intValue()).isEqualTo(1);
		assertThat(new Levenshtein().evaluate(VF, str("ab"), str("ba")).intValue()).isEqualTo(2);
		assertThat(new DamerauLevenshtein().evaluate(VF, str("kitten"), str("sitting")).intValue()).isEqualTo(3);
	}

	@Test
	void jaroFamily() {
		assertThat(dbl(new JaroSimilarity().evaluate(VF, str("MARTHA"), str("MARHTA"))))
				.isCloseTo(0.9444, within(1e-4));
		assertThat(dbl(new JaroWinkler().evaluate(VF, str("MARTHA"), str("MARHTA")))).isCloseTo(0.9611, within(1e-4));
		assertThat(dbl(new JaroSimilarity().evaluate(VF, str("CRATE"), str("TRACE")))).isCloseTo(0.7333, within(1e-4));
		assertThat(dbl(new JaroSimilarity().evaluate(VF, str(""), str("")))).isEqualTo(1.0);
		assertThat(dbl(new JaroSimilarity().evaluate(VF, str("abc"), str("xyz")))).isEqualTo(0.0);
		assertThat(dbl(new JaroWinkler().evaluate(VF, str("DWAYNE"), str("DUANE")))).isCloseTo(0.84, within(1e-4));
		assertThatThrownBy(() -> new JaroWinkler().evaluate(VF, str("a"), str("b"), VF.createLiteral(0.5)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void phonetic() {
		assertThat(new Soundex().evaluate(VF, str("Robert"))).isEqualTo(str("R163"));
		assertThat(new Soundex().evaluate(VF, str("Rupert"))).isEqualTo(str("R163"));
		assertThat(new Soundex().evaluate(VF, str("Tymczak"))).isEqualTo(str("T522"));
		assertThat(new Soundex().evaluate(VF, str("Ashcraft"))).isEqualTo(str("A261"));
		assertThat(new Soundex().evaluate(VF, str("Pfister"))).isEqualTo(str("P236"));
		assertThat(new Soundex().evaluate(VF, str("Honeyman"))).isEqualTo(str("H555"));
		assertThat(new Soundex().evaluate(VF, str("123"))).isEqualTo(str(""));
		assertThat(new Metaphone().evaluate(VF, str("Thompson"))).isEqualTo(str("0MPS"));
		assertThat(new Metaphone().evaluate(VF, str("Knight"))).isEqualTo(str("NT"));
		assertThat(new Metaphone().evaluate(VF, str("Philip"))).isEqualTo(str("FLP"));
		assertThat(new Metaphone().evaluate(VF, str("Xavier"))).isEqualTo(str("SFR"));
		assertThat(new Metaphone().evaluate(VF, str("Thumb"))).isEqualTo(str("0M"));
		assertThat(new Metaphone().evaluate(VF, str("Schmidt"), VF.createLiteral(10))).isEqualTo(str("SKMTT"));
		assertThat(new Metaphone().evaluate(VF, str("Judge"))).isEqualTo(str("JJ"));
		assertThat(new Metaphone().evaluate(VF, str("Dumb"))).isEqualTo(str("TM"));
		assertThat(new Metaphone().evaluate(VF, str("Wright"))).isEqualTo(str("RT"));
		assertThat(new Metaphone().evaluate(VF, str("Science"))).isEqualTo(str("SNS"));
	}

	@Test
	void trigramSimilarity() {
		assertThat(dbl(new TrigramSimilarity().evaluate(VF, str("word"), str("two words"))))
				.isCloseTo(0.363636, within(1e-5));
		assertThat(dbl(new TrigramSimilarity().evaluate(VF, str("Hello"), str("hello")))).isEqualTo(1.0);
		assertThat(dbl(new TrigramSimilarity().evaluate(VF, str(""), str("")))).isEqualTo(0.0);
		assertThat(TrigramSimilarity.trigrams("ab")).containsExactlyInAnyOrder("  a", " ab", "ab ");
	}

	@Test
	void ilike() {
		assertThat(new ILike().evaluate(VF, str("Hello World"), str("hello%"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("Hello World"), str("%WORLD"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("Hello World"), str("h_llo w%d"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("Hello World"), str("hello"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new ILike().evaluate(VF, str("100%"), str("100\\%"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("100x"), str("100\\%"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new ILike().evaluate(VF, str("a_b"), str("a!_b"), str("!"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("STRASSE"), str("strasse"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("aaab"), str("%a%b%"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str(""), str("%"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str(""), str("_"))).isEqualTo(BooleanLiteral.FALSE);
	}

	@Test
	void tokenizeAndNgrams() {
		assertThat(new Tokenize().evaluate(VF, str("Hello, world! It's rdf4j_core v2.")).getLabel())
				.isEqualTo("[\"Hello\",\"world\",\"It's\",\"rdf4j_core\",\"v2\"]");
		assertThat(new Ngrams().evaluate(VF, str("abcd"), VF.createLiteral(2)).getLabel())
				.isEqualTo("[\"ab\",\"bc\",\"cd\"]");
		assertThat(new Ngrams().evaluate(VF, str("ab"), VF.createLiteral(3)).getLabel()).isEqualTo("[]");
		assertThat(new Ngrams().evaluate(VF, str("a😀b"), VF.createLiteral(2)).getLabel())
				.isEqualTo("[\"a😀\",\"😀b\"]");
		assertThatThrownBy(() -> new Ngrams().evaluate(VF, str("ab"), VF.createLiteral(0)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void allRegistered() {
		for (String name : new String[] { "levenshtein", "damerauLevenshtein", "jaroSimilarity", "jaroWinkler",
				"soundex", "metaphone", "trigramSimilarity", "ilike", "tokenize", "ngrams" }) {
			assertThat(FunctionRegistry.getInstance().get(TEXTF.NAMESPACE + name)).as(name).isPresent();
		}
	}
}
